\begin{theorem}[Derivative estimates---local]
\label{thm:chow-ii-appd-local-derivative-estimates}
\source{chow-et-al-ricci-flow-part-ii:page-0394}
\uses{thm:chow-ii-shi-local-higher-derivative-estimates}
\dcref{appD:D.24}
\group{Curvature Derivative Estimates}


Let a Ricci flow be defined near the compactly contained initial ball
$\overline B_{g(0)}(p,r)$ for $0\leq t\leq T_0\leq\alpha/K$, and suppose
$|\operatorname{Rm}|\leq K$. Then
\[
 |\nabla^m\operatorname{Rm}(y,t)|\leq
 \frac{C(\alpha,K,r,n,m)}{t^{m/2}}
\]
for $y\in B_{g(0)}(p,r/2)$ and $0<t\leq T_0$.
\end{theorem}

